new:
.hero-ripple {
  position: absolute; inset: 0; z-index: 0; width: 100%; height: 100%;
  display: block; pointer-events: none;
}
/* The scripts: the first vowel of each of the twelve scripts the model reads,
   one after another, set in that script's own face and lit by the same warm
   gradient as the rings that leave it. On phones it leads the card; on wide
   screens it sits at the left, where the sound is born. */
.hero-glyph {
  position: relative; z-index: 3; width: 8rem; height: 8.6rem; margin: -0.6rem auto 0.4rem;
  font-family: var(--indic); font-weight: 400; line-height: 1;
}
.hero-glyph-face {
  position: absolute; left: 0; right: 0; top: 0; bottom: 2.4rem;
  display: flex; align-items: center; justify-content: center;
  font-size: 5.4rem;
  background: linear-gradient(160deg, #A8330E 0%, #C2410C 48%, #D8842F 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  opacity: 0; transform: translateY(10px) scale(0.96);
  transition: opacity 0.7s cubic-bezier(0.22, 1, 0.36, 1), transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
.hero-glyph-face.is-on { opacity: 1; transform: none; }
.hero-glyph-cap {
  position: absolute; left: -1rem; right: -1rem; bottom: 0; text-align: center;
  font: 600 0.74rem/1.35 var(--font-body); color: var(--text-muted);
  transition: opacity 0.35s ease;
}
.hero-glyph-cap .k { display: block; font-weight: 500; color: var(--color-11); }
.hero-glyph-cap.is-off { opacity: 0; }
@media (min-width: 768px) {
  .hero-glyph { position: absolute; left: 1.9rem; top: 50%; margin: 0; transform: translateY(-58%); width: 9.6rem; height: 11rem; }
  .hero-glyph-face { font-size: 7.4rem; bottom: 2.6rem; }
}

old:
/* ── Hero: voice bars ────────────────────────────────────────────────────
 * A chart-like field borrowed from the sibling OCR story, shaped here by a
 * real Indic-Speak envelope. CSS owns the motion, so the hero needs no paint
 * loop while the reader scrolls.
 * ──────────────────────────────────────────────────────────────────────── */
(function () {
  var field = need('heroBars');
  if (!field) return;
  var amp = HERO.amp;
  var count = 56;
  for (var i = 0; i < count; i++) {
    var from = Math.floor(i * amp.length / count);
    var to = Math.max(from + 1, Math.floor((i + 1) * amp.length / count));
    var level = 0;
    for (var j = from; j < to; j++) level = Math.max(level, amp[j]);
    var bar = document.createElement('span');
    bar.className = 'hero-bar';
    bar.style.height = (12 + level * 72).toFixed(1) + '%';
    bar.style.animationDelay = (-i * 0.075).toFixed(3) + 's';
    bar.style.animationDuration = (2.4 + (i % 7) * 0.16).toFixed(2) + 's';
    field.appendChild(bar);
  }
})();

new:
/* ── Hero: the scripts ───────────────────────────────────────────────────
 * The first vowel of each of the twelve scripts the model reads, one after
 * another, with the script's name and how many of the 22 languages write in
 * it. The scripts and their languages come from the language table, so the
 * hero cannot disagree with the rest of the post. The rings below are born
 * from this letter: the text is the source of the sound.
 * ──────────────────────────────────────────────────────────────────────── */
(function () {
  var box = need('heroGlyph');
  if (!box) return;
  var faces = [need('heroGlyphA'), need('heroGlyphB')], cap = need('heroGlyphCap');
  var VOWEL = { 'Devanagari': 'अ', 'Bengali–Assamese': 'অ', 'Gujarati': 'અ', 'Gurmukhi': 'ਅ',
                'Odia': 'ଅ', 'Tamil': 'அ', 'Telugu': 'అ', 'Kannada': 'ಅ', 'Malayalam': 'അ',
                'Perso-Arabic': 'ا', 'Meitei Mayek': 'ꯑ', 'Ol Chiki': 'ᱟ' };
  var by = {}, scripts = [];
  D.languages.forEach(function (l) {
    if (!by[l.script]) { by[l.script] = { name: l.script, glyph: VOWEL[l.script], langs: [] }; scripts.push(by[l.script]); }
    by[l.script].langs.push(l.name);
  });
  // Most-written scripts first, so the card opens on Devanagari.
  scripts.sort(function (p, q) { return q.langs.length - p.langs.length; });

  function label(s) {
    var k = s.langs.length > 1 ? s.langs.length + ' languages'
          : s.langs[0] !== s.name ? s.langs[0] : '';
    return esc(s.name) + (k ? '<span class="k">' + esc(k) + '</span>' : '');
  }
  var i = 0, on = 0;
  function show(s) {
    var next = faces[1 - on];
    next.textContent = s.glyph;
    faces[on].classList.remove('is-on');
    next.classList.add('is-on');
    on = 1 - on;
    cap.classList.add('is-off');
    setTimeout(function () { cap.innerHTML = label(s); cap.classList.remove('is-off'); }, 300);
  }
  show(scripts[0]);
  if (REDUCED) return;
  var HOLD = 2600, visible = true;
  setInterval(function () {
    if (!visible) return;
    i = (i + 1) % scripts.length;
    show(scripts[i]);
  }, HOLD);
  if (window.IntersectionObserver) {
    new IntersectionObserver(function (es) { visible = es[0].isIntersecting; }).observe(box);
  }
})();

